(2, 140, 1655599823, 'a boy', 0, 1, 'm@qqmcin.com', NULL, '115.206.53.30', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/102.0.5005.124 Safari/537.36 Edg/102.0.1245.44', '好！', 'comment', 'waiting', 0),
(3, 183, 1657002223, '朱哥', 0, 1, 'admin@admin.com', NULL, '122.224.203.238', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/103.0.0.0 Safari/537.36', 'location  ~*^.+$ {         \r\n          proxy_pass http://127.0.0.1:5001;  #请求转向mysvr 定义的服务器列表    \r\n          proxy_set_header Host $host;\r\n          proxy_set_header X-Real-IP $remote_addr;\r\n          proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;     \r\n          #add_header Cache-Control no-store;\r\n          #add_header Pragma  no-cache;\r\n          #proxy_http_version 1.1;    #使用长连接必须使HTTP 1.1以上\r\n          #proxy_set_header Connection \"Keep-Alive\";\r\n        }', 'comment', 'approved', 0);
